   778  //Create and parse the movie for READ - EDIT only
   779  GF_ISOFile *gf_isom_open_file(const char *fileName, GF_ISOOpenMode OpenMode, const char *tmp_dir)
   780  {
   781          GF_Err e;
   782          u64 bytes;
   783          GF_ISOFile *mov = gf_isom_new_movie();
   784          if (!mov || !fileName) return NULL;
   785
   786          mov->fileName = gf_strdup(fileName);
   787          mov->openMode = OpenMode;
   788
   789  #ifndef GPAC_DISABLE_ISOM_FRAGMENTS
   790          if (OpenMode==GF_ISOM_OPEN_READ_DUMP)
   791                  mov->store_traf_map = GF_TRUE;
   792  #endif
   793
   794          if ( (OpenMode == GF_ISOM_OPEN_READ) || (OpenMode == GF_ISOM_OPEN_READ_DUMP) || (OpenMode == GF_ISOM_OPEN_READ_EDIT) ) {
   795                  if (OpenMode == GF_ISOM_OPEN_READ_EDIT) {
   796                          mov->openMode = GF_ISOM_OPEN_READ_EDIT;
   797
   798                          // create a memory edit map in case we add samples, typically during import
   799                          e = gf_isom_datamap_new(NULL, tmp_dir, GF_ISOM_DATA_MAP_WRITE, & mov->editFileMap);
   800                          if (e) {
   801                                  gf_isom_set_last_error(NULL, e);
   802                                  gf_isom_delete_movie(mov);
   803                                  return NULL;
   804                          }
   805                  } else {
   806                          mov->openMode = GF_ISOM_OPEN_READ;
   807                  }
   808                  mov->es_id_default_sync = -1;
   809                  //for open, we do it the regular way and let the GF_DataMap assign the appropriate struct
   810                  //this can be FILE (the only one supported...) as well as remote
   811                  //(HTTP, ...),not suported yet
   812                  //the bitstream IS PART OF the GF_DataMap
   813                  //as this is read-only, use a FileMapping. this is the only place where
   814                  //we use file mapping
   815                  e = gf_isom_datamap_new(fileName, NULL, GF_ISOM_DATA_MAP_READ_ONLY, &mov->movieFileMap);
   816                  if (e) {
   817                          gf_isom_set_last_error(NULL, e);
   818                          gf_isom_delete_movie(mov);
   819                          return NULL;
   820                  }
   821
   822                  if (OpenMode == GF_ISOM_OPEN_READ_DUMP) {
   823                          mov->FragmentsFlags |= GF_ISOM_FRAG_READ_DEBUG;
   824                  }
   825          } else {
   826
   827  #ifdef GPAC_DISABLE_ISOM_WRITE
   828                  //not allowed for READ_ONLY lib
   829                  gf_isom_delete_movie(mov);
   830                  gf_isom_set_last_error(NULL, GF_ISOM_INVALID_MODE);
   831                  return NULL;
   832
   833  #else
   834
   835                  //set a default output name for edited file
   836                  mov->finalName = (char*)gf_malloc(strlen(fileName) + 5);
   837                  if (!mov->finalName) {
   838                          gf_isom_set_last_error(NULL, GF_OUT_OF_MEM);
   839                          gf_isom_delete_movie(mov);
   840                          return NULL;
   841                  }
   842                  strcpy(mov->finalName, "out_");
   843                  strcat(mov->finalName, fileName);
   844
   845                  //open the original file with edit tag
   846                  e = gf_isom_datamap_new(fileName, NULL, GF_ISOM_DATA_MAP_EDIT, &mov->movieFileMap);
   847                  //if the file doesn't exist, we assume it's wanted and create one from scratch
   848                  if (e) {
   849                          gf_isom_set_last_error(NULL, e);
   850                          gf_isom_delete_movie(mov);
   851                          return NULL;
   852                  }
   853                  //and create a temp fileName for the edit
   854                  e = gf_isom_datamap_new("_gpac_isobmff_tmp_edit", tmp_dir, GF_ISOM_DATA_MAP_WRITE, & mov->editFileMap);
   855                  if (e) {
   856                          gf_isom_set_last_error(NULL, e);
   857                          gf_isom_delete_movie(mov);
   858                          return NULL;
   859                  }
